function sourceSection(key,index) {
 const s=sourceTopics[key][index];
 let title=s.title.replace(/^السلايد\s*\d+\s*[:：]\s*/,'').replace(/^\d+\.\s*/,'').replace(/\s*\+ تاسك اللاعبين/,'').replace('المنقذ السحري','حساب المقاسات').replace('وحش التخطيط:','').replace('الجبار','').replace('الجوكر','').replace('التعديل الشامل','تحويل العناصر').replace('הפليكس','الفليكس');
 const correction=topicCorrections[`${key}:${index}`];
 const explanations=correction ? correction.map(p=>`<p>${learnText(p)}</p>`).join('') : s.explanations.map(e=>e.items.length?`<${e.tag}>${e.items.map(item=>`<li>${learnText(item)}</li>`).join('')}</${e.tag}>`:`<p>${learnText(e.text)}</p>`).join('');
 const extra=deeperNotes[key]?.[index];
 let snippets=s.code.map(text=>text.replace(/console\.log\(myAccount\.#balance\);/,'// console.log(myAccount.#balance);').replace(/opacity: 0\.8; \/\* شفاف بنسبة 80% \*\//,'opacity: 0.8; /* عتامة 80%، شفافية 20% */'));
 if(key==='advanced'&&[5,6,7].includes(index)) snippets=snippets.map(text=>text.replace(/(let|const) response = await fetch\(([^;]+)\);/g,'$1 response = await fetch($2);\n    if (!response.ok) throw new Error("تعذّر تحميل البيانات");').replace('// الرد جه، بس محتاجين نحوله لـ json','if (!response.ok) throw new Error("تعذّر تحميل البيانات");\n      // نقرا جسم الاستجابة كـ JSON').replace('https://link-msh-mawgod.com','https://jsonplaceholder.typicode.com/not-found'));
 if(key==='dom'&&index===13) snippets=[`<!-- index.html -->
<form id="task-form">
  <label for="task-input">المهمة</label>
  <input id="task-input" required>
  <button type="submit">إضافة</button>
</form>
<ul id="tasks-list"></ul>
<script src="main.js" defer></script>`,`// main.js
const form = document.querySelector('#task-form');
const input = document.querySelector('#task-input');
const list = document.querySelector('#tasks-list');
form.addEventListener('submit', event => {
  event.preventDefault();
  const title = input.value.trim();
  if (!title) return;
  const item = document.createElement('li');
  const text = document.createElement('span');
  text.textContent = title;
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = 'حذف';
  button.addEventListener('click', () => item.remove());
  item.append(text, button);
  list.append(item);
  input.value = '';
  input.focus();
});`];
 if(key==='html'&&index===4) snippets=[`<!doctype html>
<html lang="ar" dir="rtl">
  <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>أول صفحة ليا</title>
  </head>
  <body>
    <h1>أهلًا بيك في موقعي</h1>
    <p>دي أول خطوة في تعلّم الويب.</p>
  </body>
</html>`];
 if(key==='html'&&[13,14,15].includes(index)) snippets=snippets.map(text=>text.replace(/ border="1"| cellpadding="10"/g,''));
 const blocks=snippets.flatMap(text=>{
   const parts=[];let rest=text;
   const cssMarker=rest.match(/\/\*\s*(?:\d+\.\s*)?(?:CSS|كود الـ CSS)[\s\S]*?\*\//i);
   const jsMarker=rest.match(/\/\/\s*(?:\d+\.\s*)?(?:JS|كود الـ JS)[^\n]*/i);
   const first=cssMarker?.index??jsMarker?.index;
   if(first!==undefined&&rest.slice(0,first).trim().startsWith('<')){
     parts.push(code(rest.slice(0,first),'index.html'));
     if(cssMarker){const cssEnd=jsMarker?.index??rest.length;parts.push(code(rest.slice(cssMarker.index+cssMarker[0].length,cssEnd),'styles.css'));}
     if(jsMarker)parts.push(code(rest.slice(jsMarker.index+jsMarker[0].length),'main.js'));
     return parts;
   }
   return [code(text,text.trim().startsWith('<')?'index.html':key==='css'||key==='responsive'?'styles.css':'main.js')];
 });
 return {id:`${key}-${index+1}`,title,html:`${explanations}${blocks.join('')}${extra?note('نفهمها في التطبيق',learnText(extra)):''}`};
}
const pick=(key,start,end)=>Array.from({length:end-start+1},(_,i)=>sourceSection(key,start+i));
