 html:{id:'html',name:'HTML',label:'ابدأ بالهيكل',tag:'01 · الأساس',icon:'〈/〉',desc:'اعمل صفحة لها معنى: محتوى، صور، روابط، جداول وفورمات.',prerequisite:'ابدأ هنا، مش محتاج خبرة سابقة.',lessons:htmlLessons,color:'orange',reference:'https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content'},
